    // ---- JSON, shared by the recorder and the bridge (generated by fast-anything)
    internal static class Json
    {
        internal sealed class Unsupported : Exception
        {
            public Unsupported(string m) : base(m) { }
        }

        public static readonly JsonSerializerOptions Options = MakeOptions();

        static JsonSerializerOptions MakeOptions()
        {
            var o = new JsonSerializerOptions();
            o.Converters.Add(new BytesAsNumbers());
            return o;
        }

        // byte[] travels as a list of numbers, like every other array (System.Text.Json would use base64)
        sealed class BytesAsNumbers : JsonConverter<byte[]>
        {
            public override byte[]? Read(ref Utf8JsonReader r, Type t, JsonSerializerOptions o)
            {
                if (r.TokenType == JsonTokenType.Null) return null;
                var bytes = new List<byte>();
                while (r.Read() && r.TokenType != JsonTokenType.EndArray) bytes.Add(r.GetByte());
                return bytes.ToArray();
            }

            public override void Write(Utf8JsonWriter w, byte[] v, JsonSerializerOptions o)
            {
                w.WriteStartArray();
                foreach (var b in v) w.WriteNumberValue(b);
                w.WriteEndArray();
            }
        }

        public static object? Dec(JsonNode? n, Type t) => n is null ? null : JsonSerializer.Deserialize(n, t, Options);

        public static string Enc(object? v)
        {
            var b = new StringBuilder();
            Enc(v, b);
            return b.ToString();
        }

        static void Number(string s, StringBuilder b)
        {
            b.Append(s);
            if (s.IndexOfAny(new[] { '.', 'E', 'e' }) < 0) b.Append(".0");
        }

        static void Enc(object? v, StringBuilder b)
        {
            var inv = CultureInfo.InvariantCulture;
            switch (v)
            {
                case null: b.Append("null"); break;
                case bool x: b.Append(x ? "true" : "false"); break;
                case string s: Str(s, b); break;
                case char c: Str(c.ToString(), b); break;
                case int or long or short or sbyte or byte or uint or ulong or ushort:
                    b.Append(((IFormattable)v).ToString(null, inv));
                    break;
                case double d:
                    if (!double.IsFinite(d)) throw new Unsupported("NaN or Infinity");
                    Number(d.ToString("R", inv), b);
                    break;
                case float f:
                    if (!float.IsFinite(f)) throw new Unsupported("NaN or Infinity");
                    Number(f.ToString("R", inv), b);
                    break;
                case IDictionary m:
                {
                    b.Append('{');
                    bool first = true;
                    foreach (DictionaryEntry e in m)
                    {
                        if (e.Key is not string k) throw new Unsupported("Dictionary with non-string keys");
                        if (!first) b.Append(',');
                        first = false;
                        Str(k, b);
                        b.Append(':');
                        Enc(e.Value, b);
                    }
                    b.Append('}');
                    break;
                }
                case IEnumerable xs:
                {
                    b.Append('[');
                    bool first = true;
                    foreach (var x in xs)
                    {
                        if (!first) b.Append(',');
                        first = false;
                        Enc(x, b);
                    }
                    b.Append(']');
                    break;
                }
                default: throw new Unsupported(v.GetType().Name);
            }
        }

        public static void Str(string s, StringBuilder b)
        {
            b.Append('"');
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (char.IsHighSurrogate(c) && i + 1 < s.Length && char.IsLowSurrogate(s[i + 1]))
                {
                    b.Append(c).Append(s[++i]);
                    continue;
                }
                if (char.IsSurrogate(c)) throw new Unsupported("string with a lone surrogate");
                switch (c)
                {
                    case '"': b.Append("\\\""); break;
                    case '\\': b.Append("\\\\"); break;
                    case '\n': b.Append("\\n"); break;
                    case '\r': b.Append("\\r"); break;
                    case '\t': b.Append("\\t"); break;
                    default:
                        if (c < 0x20) b.Append("\\u").Append(((int)c).ToString("x4")); else b.Append(c);
                        break;
                }
            }
            b.Append('"');
        }

        public static string Str(string s)
        {
            var b = new StringBuilder();
            Str(s, b);
            return b.ToString();
        }
    }
